using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    internal StateFingerprint TaskExhaustWitnessKey(CombatPredictionSimulator simulator)
    {
        SimulatedCombatState combat = (SimulatedCombatState)simulator.State.CombatState;
        return BuildStateKey(combat.GetPlayerTurnNumber(_player), simulator.State.GetCreature(_player.Creature),
            simulator.State.GetPlayerCombatState(_player), combat, simulator, simulator.ShuffleEventCount,
            new HashSet<uint>());
    }
}

internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskExhaustOrderContractAsync(CombatState live, Player player)
    {
        string variant = Environment.GetEnvironmentVariable("TASK_EXHAUST_ORDER_CASE")
            ?? throw new InvalidOperationException("Exhaust-order fixture requires an explicit native order.");
        if (variant is not ("buff-first" or "attack-first"))
            throw new InvalidOperationException("Unknown exhaust-order fixture case: " + variant);
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        await ClearPlayerPilesAsync(player);
        foreach (Creature enemy in live.Enemies) await CreatureCmd.SetMaxAndCurrentHp(enemy, 100);
        await InjectCardAsync(live, player, new() { CardId = "EIDOLON", Pile = "Hand" });
        foreach (string id in variant == "buff-first"
            ? new[] { "INFLAME", "STRIKE_IRONCLAD" } : new[] { "STRIKE_IRONCLAD", "INFLAME" })
        {
            var card = (await InjectCardAsync(live, player, new() { CardId = id, Pile = "Exhaust" })).Single();
            CardCmd.ApplyKeyword(card, CardKeyword.Ethereal);
        }
        SetEnergy(player, 3);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null);
        SolverDisplayNames names = SolverDisplayNames.Capture(live);
        CombatBeamSolver ordered = new(root, names, BattleDamageTracker.Observe(live), policy,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        CombatBeamSolver projected = new(root, names, BattleDamageTracker.Observe(live),
            policy with { PileOrderInvariantMask = 8 }, potionPolicyOverride: SolverPotionPolicy.Disabled);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(
            player, sim, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
        string Rng(CombatPredictionSimulator sim) => JsonSerializer.Serialize(new {
            sim.Rng.ShuffleState, sim.Rng.CombatCardGenerationState, sim.Rng.CombatPotionGenerationState,
            sim.Rng.CombatCardSelectionState, sim.Rng.CombatEnergyCostsState, sim.Rng.CombatTargetsState,
            sim.Rng.CombatOrbGenerationState, sim.Rng.MonsterAiState, sim.Rng.NicheState, sim.ShuffleEventCount
        });
        string Full(CombatPredictionSimulator sim) => State(sim) + "\nKEY=" + ordered.TaskExhaustWitnessKey(sim)
            + "\nHISTORY=" + CardContinuationContractHistoryText(sim) + "\nRNG=" + Rng(sim)
            + "\nFLAGS=" + JsonSerializer.Serialize(new { sim.TerminalStamp, sim.IsInProgress, sim.IsAboutToLose });
        static void Equal(string expected, string actual, string label)
        {
            if (expected != actual) throw new InvalidOperationException(label + " differs:\nEXPECTED\n"
                + expected + "\nACTUAL\n" + actual);
        }
        static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
        int EnemyHp(CombatPredictionSimulator sim) => root.Enemies.Sum(enemy => sim.State.GetCreature(enemy).CurrentHp);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        string parentBefore = Full(parent);
        CombatPredictionSimulator reverse = parent.Fork();
        SimCardPile reversePile = reverse.State.GetPlayerCombatState(player).ExhaustPile;
        PredictedCard[] reverseCards = reversePile.Cards.Reverse().ToArray();
        reversePile.Clear();
        foreach (PredictedCard card in reverseCards) reversePile.Add(card);
        if (ordered.TaskExhaustWitnessKey(parent) == ordered.TaskExhaustWitnessKey(reverse))
            throw new InvalidOperationException("Ordered witness failed to distinguish exhaust sequence.");
        if (projected.TaskExhaustWitnessKey(parent) != projected.TaskExhaustWitnessKey(reverse))
            throw new InvalidOperationException("The complete mask8 keys do not match this counterexample.");
        Equal(Rng(parent), Rng(reverse), "same starting nine RNG streams");
        string reverseBefore = Full(reverse);
        CombatPredictionSimulator Replay(CombatPredictionSimulator source)
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator sim = source.Fork();
            SimulatedCombatState combat = (SimulatedCombatState)sim.State.CombatState;
            PredictedCard eidolon = sim.State.GetPlayerCombatState(player).Hand.Cards.Single();
            ForkableSet<uint> deaths = [];
            using (combat.BeginCardExecutionScope(deaths))
                if (!sim.ManualPlay(eidolon, null, out _))
                    throw new InvalidOperationException("Eidolon is not playable in the witness.");
            if (!CorePowerSupport.ApplyEnemyDeathPowers(sim, combat, combat.KnownEnemies, deaths)
                || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat) || sim.HasPendingChoice)
                throw new InvalidOperationException("Witness unexpectedly left a pending boundary.");
            sim.CheckWinCondition(root.StartTurnNumber);
            return sim;
        }
        CombatPredictionSimulator expected = Replay(parent), opposite = Replay(reverse);
        int damage = EnemyHp(parent) - EnemyHp(expected);
        int oppositeDamage = EnemyHp(reverse) - EnemyHp(opposite);
        if (damage == oppositeDamage || State(expected) == State(opposite))
            throw new InvalidOperationException("Exhaust order did not produce a combat consequence.");
        Equal(parentBefore, Full(parent), "first parent after replay");
        Equal(reverseBefore, Full(reverse), "reversed parent after replay");
        string expectedBefore = Full(expected);
        CombatPredictionSimulator[] children = Enumerable.Range(0, 16).Select(_ => expected.Fork()).ToArray();
        foreach (CombatPredictionSimulator child in children)
            Equal(expectedBefore, Full(child), "fork complete state/history/RNG");
        await Task.WhenAll(children.Select((child, index) => Task.Run(() => {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            ((SimulatedCombatState)child.State.CombatState).Apply<StrengthPower>(
                player.Creature, index + 1, player.Creature);
        })));
        for (int index = 0; index < children.Length; index++)
        {
            int strength = ((SimulatedCombatState)children[index].State.CombatState)
                .GetPower<StrengthPower>(player.Creature)?.Amount ?? 0;
            if (strength != index + 3) throw new InvalidOperationException("Fork siblings shared strength state.");
            Equal(Rng(expected), Rng(children[index]), "fork RNG isolation");
        }
        Equal(expectedBefore, Full(expected), "fork source remains unchanged");
        Equal(parentBefore, Full(parent), "root parent remains unchanged");
        Equal(reverseBefore, Full(reverse), "reversed parent remains unchanged");
        Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "shadow work does not mutate live");
        using CancellationTokenSource deadline = new(TimeSpan.FromSeconds(12));
        var nativeCard = player.PlayerCombatState!.Hand.Cards.Single();
        GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
            queued => queued is PlayCardAction played
                && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), nativeCard),
            () => { if (!nativeCard.TryManualPlay(null)) throw new InvalidOperationException("Native Eidolon is not playable."); },
            deadline.Token);
        await action.CompletionTask.WaitAsync(deadline.Token);
        Equal(State(expected), ContinuationStamp.CaptureLive(live).StateText, "native full state and nine RNG streams");
        Creature target = root.Enemies[0];
        AssertSnapshotEqual(CaptureSimulated(expected, (SimulatedCombatState)expected.State.CombatState,
            player, target), CaptureActual(live, player, target), "EXHAUST_ORDER", variant);
        _completedChecks.Add("ExhaustOrder:CompleteProjectionMatches:OrderedKeyDiffers:DifferentDamage:NativeFullStateMatches:SixteenForks:ParentSiblingLiveRngIsolation");
        _completedChecks.Add("TASK_EXHAUST_ORDER " + JsonSerializer.Serialize(new {
            variant, damage, oppositeDamage, OriginalKey = ordered.TaskExhaustWitnessKey(parent),
            ProjectedKey = projected.TaskExhaustWitnessKey(parent), RootRng = Rng(parent),
            NativeStateSha256 = Hash(ContinuationStamp.CaptureLive(live).StateText),
            SimulatedStateSha256 = Hash(State(expected)), ParentStateSha256 = Hash(parentBefore)
        }));
    }
}

